INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7699841, 1263835, 30861, '<td valign="top">Fine job, spiffy :-)</td>', 'Fine job, spiffy :-)', '2021-08-30 01:08:22.000000', NULL, 1),
(7699856, 1263686, 67258, '<td valign="top">Excellent mono conversion.  Crisp throughout, but with no sign of over-sharpening artefacts.  Definite impact in composition.</td>', 'Excellent mono conversion.  Crisp throughout, but with no sign of over-sharpening artefacts.  Definite impact in composition.', '2021-08-30 06:36:05.000000', NULL, 1),
(7699858, 1263835, 67258, '<td valign="top">I had to look up Scituate, thinking it was some word new to my vocabulary.  I discover it is an area of Massachusetts - and very nice it looks.  Im not overly keen on the slight toning, but that is very much down to a subjective personal choice.  I also wish the top of the building to the left wasnt there, along with the small amount of vegetation, but removing them would take from the integrity of the composition.  What I love - everything else about the composition; the very deep dof; the tonal range, especially of the rocks leading through to the lighthouse; the sweeping sky, with the clouds providing diagonal balance to the foreground rocks.  All in all, a very pleasing photo, and well considered composition.</td>', 'I had to look up Scituate, thinking it was some word new to my vocabulary.  I discover it is an area of Massachusetts - and very nice it looks.  Im not overly keen on the slight toning, but that is very much down to a subjective personal choice.  I also wish the top of the building to the left wasnt there, along with the small amount of vegetation, but removing them would take from the integrity of the composition.  What I love - everything else about the composition; the very deep dof; the tonal range, especially of the rocks leading through to the lighthouse; the sweeping sky, with the clouds providing diagonal balance to the foreground rocks.  All in all, a very pleasing photo, and well considered composition.', '2021-08-30 06:46:19.000000', NULL, 1),
(7699859, 1263843, 67258, '<td valign="top">An interesting scene, with a unique perspective. Personally, I would prefer more contrast, deeper blacks, and brighter whites, but then that wouldnt be the photo you wanted to take.</td>', 'An interesting scene, with a unique perspective. Personally, I would prefer more contrast, deeper blacks, and brighter whites, but then that wouldnt be the photo you wanted to take.', '2021-08-30 06:48:17.000000', NULL, 1),
(7699860, 1263865, 67258, '<td valign="top">Technically fine, but Im not convinced your subject benefits from a mono conversion.</td>', 'Technically fine, but Im not convinced your subject benefits from a mono conversion.', '2021-08-30 06:49:50.000000', NULL, 1),
(7699861, 1263825, 67258, '<td valign="top">Northern Ireland and marching season?  A good record shot.  The banner and church in the diagonal make for an interesting comment on the 8nextricable link of religion and politics in the country.</td>', 'Northern Ireland and marching season?  A good record shot.  The banner and church in the diagonal make for an interesting comment on the 8nextricable link of religion and politics in the country.', '2021-08-30 06:52:46.000000', NULL, 1),
(7699862, 1263850, 67258, '<td valign="top">Fascinating and appealing patterns.  Crisp and well composed.</td>', 'Fascinating and appealing patterns.  Crisp and well composed.', '2021-08-30 06:53:39.000000', NULL, 1),
(7699863, 1263872, 67258, '<td valign="top">I like the concept, and the gentle tones, but not so keen on the intrusion of the frame of the foreground chair.</td>', 'I like the concept, and the gentle tones, but not so keen on the intrusion of the frame of the foreground chair.', '2021-08-30 06:56:46.000000', NULL, 1),
