(7700540, 1263870, 97225, '<td valign="top">Nice environmental portrait. I love the way the spray catches the light.</td>', 'Nice environmental portrait. I love the way the spray catches the light.', '2021-09-06 00:10:50.000000', NULL, 1),
(7700541, 1263862, 97225, '<td valign="top">A very engaging image. I like the random patterns in the foreground road, the one way sign and the car going the other way, and it''s all topped off with a wonderful sky.</td>', 'A very engaging image. I like the random patterns in the foreground road, the one way sign and the car going the other way, and it''s all topped off with a wonderful sky.', '2021-09-06 00:13:59.000000', NULL, 1),
